{"type":"assistant","message":{"model":"claude-opus-4-6","id":"msg_01LiZMpyqZ1qenyCghoPbdMb","type":"message","role":"assistant","content":[{"type":"tool_use","id":"toolu_01WPE3Dz3C4bzk3fZAurTDBc","name":"Write","input":{"file_path":"/home/ubuntu/.agent-ml-research-be-idea-gen-0515-2/projects/importance_margin_vla_compress/artifacts/eval_xvla_pruning_libero.py","content":"\"\"\"X-VLA L2-norm vision token pruning evaluation on LIBERO.\n\nPruning: after Florence-2 image_projection (producing N vision tokens),\ncompute L2 norm per token, keep top k*N tokens by magnitude.\nPruned tokens are removed before merging with text and entering the encoder.\n\nX-VLA-Libero uses the original HF format (trust_remote_code=True), not lerobot.\nAction output is 10D (3 pos + 6D rotation + 1 gripper), converted to 7D for LIBERO.\n\nUsage:\n    CUDA_VISIBLE_DEVICES=1 MUJOCO_GL=egl python eval_xvla_pruning_libero.py \\\n        --pretrained_dir /root/autodl-tmp/.hf_cache/models--2toINF--X-VLA-Libero/snapshots/... \\\n        --suite libero_object --k_ratio 0.5 --num_episodes 50\n\"\"\"\nfrom __future__ import annotations\n\nimport argparse\nimport json\nimport logging\nimport os\nimport sys\nimport time as time_mod\nimport types\nfrom pathlib import Path\n\nos.environ.setdefault(\"MUJOCO_GL\", \"egl\")\nos.environ.setdefault(\"TRANSFORMERS_OFFLINE\", \"1\")\nos.environ.setdefault(\"HF_HUB_OFFLINE\", \"1\")\n\nimport numpy as np\nimport torch\n\nsys.path.insert(0, str(Path(__file__).resolve().parent))\n\nlogging.basicConfig(\n    level=logging.INFO,\n    format=\"%(asctime)s [%(levelname)s] %(message)s\",\n    datefmt=\"%Y-%m-%d %H:%M:%S\",\n)\nlog = logging.getLogger(__name__)\n\nSUITE_MAX_STEPS = {\n    \"libero_spatial\": 280,\n    \"libero_object\": 280,\n    \"libero_goal\": 300,\n    \"libero_10\": 520,\n    \"libero_90\": 400,\n}\n\nIMAGENET_MEAN = np.array([0.485, 0.456, 0.406], dtype=np.float32)\nIMAGENET_STD = np.array([0.229, 0.224, 0.225], dtype=np.float32)\n\n\ndef parse_args():\n    p = argparse.ArgumentParser(description=\"X-VLA L2-norm pruning eval on LIBERO\")\n    p.add_argument(\"--pretrained_dir\", type=str, required=True)\n    p.add_argument(\"--suite\", type=str, default=\"libero_object\",\n                   choices=list(SUITE_MAX_STEPS.keys()))\n    p.add_argument(\"--k_ratio\", type=float, default=1.0,\n                   help=\"Fraction of vision tokens to KEEP (1.0 = no pruning)\")\n    p.add_argument(\"--num_episodes\", type=int, default=50)\n    p.add_argument(\"--gpu\", type=int, default=0)\n    p.add_argument(\"--seed\", type=int, default=42)\n    p.add_argument(\"--max_steps\", type=int, default=None)\n    p.add_argument(\"--action_horizon\", type=int, default=30)\n    p.add_argument(\"--num_denoising_steps\", type=int, default=10)\n    p.add_argument(\"--output\", type=str, default=None)\n    p.add_argument(\"--task_ids\", type=str, default=None)\n    return p.parse_args()\n\n\n# ---------------------------------------------------------------------------\n# State helpers\n# ---------------------------------------------------------------------------\n\ndef quat_to_axis_angle(quat: np.ndarray) -> np.ndarray:\n    q = quat.astype(np.float64)\n    w = np.clip(q[3], -1.0, 1.0)\n    den = np.sqrt(max(1.0 - w * w, 0.0))\n    if den > 1e-10:\n        angle = 2.0 * np.arccos(w)\n        axis = q[:3] / den\n        return (axis * angle).astype(np.float32)\n    return np.zeros(3, dtype=np.float32)\n\n\ndef extract_state(obs: dict) -> np.ndarray:\n    rs = obs[\"robot_state\"]\n    eef_pos = np.asarray(rs[\"eef\"][\"pos\"], dtype=np.float32)\n    eef_quat = np.asarray(rs[\"eef\"][\"quat\"], dtype=np.float64)\n    gripper_qpos = np.asarray(rs[\"gripper\"][\"qpos\"], dtype=np.float32)\n    eef_aa = quat_to_axis_angle(eef_quat)\n    return np.concatenate([eef_pos, eef_aa, gripper_qpos])\n\n\n# ---------------------------------------------------------------------------\n# 6D rotation -> axis-angle conversion\n# ---------------------------------------------------------------------------\n\ndef _mat2quat(rotation_matrix: np.ndarray) -> np.ndarray:\n    \"\"\"3x3 rotation matrix -> quaternion [x,y,z,w].\"\"\"\n    m = rotation_matrix\n    trace = m[0, 0] + m[1, 1] + m[2, 2]\n    if trace > 0:\n        s = 0.5 / np.sqrt(trace + 1.0)\n        w = 0.25 / s\n        x = (m[2, 1] - m[1, 2]) * s\n        y = (m[0, 2] - m[2, 0]) * s\n        z = (m[1, 0] - m[0, 1]) * s\n    elif m[0, 0] > m[1, 1] and m[0, 0] > m[2, 2]:\n        s = 2.0 * np.sqrt(1.0 + m[0, 0] - m[1, 1] - m[2, 2])\n        w = (m[2, 1] - m[1, 2]) / s\n        x = 0.25 * s\n        y = (m[0, 1] + m[1, 0]) / s\n        z = (m[0, 2] + m[2, 0]) / s\n    elif m[1, 1] > m[2, 2]:\n        s = 2.0 * np.sqrt(1.0 + m[1, 1] - m[0, 0] - m[2, 2])\n        w = (m[0, 2] - m[2, 0]) / s\n        x = (m[0, 1] + m[1, 0]) / s\n        y = 0.25 * s\n        z = (m[1, 2] + m[2, 1]) / s\n    else:\n        s = 2.0 * np.sqrt(1.0 + m[2, 2] - m[0, 0] - m[1, 1])\n        w = (m[1, 0] - m[0, 1]) / s\n        x = (m[0, 2] + m[2, 0]) / s\n        y = (m[1, 2] + m[2, 1]) / s\n        z = 0.25 * s\n    return np.array([x, y, z, w], dtype=np.float64)\n\n\ndef _quat2axisangle(quat: np.ndarray) -> np.ndarray:\n    \"\"\"Quaternion [x,y,z,w] -> axis-angle (3,).\"\"\"\n    q = quat.copy()\n    if q[3] < 0:\n        q = -q\n    theta = 2.0 * np.arccos(np.clip(q[3], -1.0, 1.0))\n    sin_half = np.sin(theta / 2.0)\n    if abs(sin_half) < 1e-8:\n        return np.zeros(3, dtype=np.float64)\n    axis = q[:3] / sin_half\n    return (axis * theta).astype(np.float64)\n\n\ndef rotate6d_to_axis_angle(r6d: np.ndarray) -> np.ndarray:\n    \"\"\"Convert 6D rotation to axis-angle. r6d: (N,6) -> (N,3).\"\"\"\n    squeeze = False\n    if r6d.ndim == 1:\n        r6d = r6d[None, :]\n        squeeze = True\n    a1 = r6d[:, 0:3]\n    a2 = r6d[:, 3:6]\n    b1 = a1 / (np.linalg.norm(a1, axis=-1, keepdims=True) + 1e-6)\n    dot = np.sum(b1 * a2, axis=-1, keepdims=True)\n    b2_orth = a2 - dot * b1\n    b2 = b2_orth / (np.linalg.norm(b2_orth, axis=-1, keepdims=True) + 1e-6)\n    b3 = np.cross(b1, b2, axis=-1)\n    results = []\n    for i in range(r6d.shape[0]):\n        rot_mat = np.stack([b1[i], b2[i], b3[i]], axis=-1)\n        quat = _mat2quat(rot_mat)\n        aa = _quat2axisangle(quat)\n        results.append(aa)\n    out = np.array(results, dtype=np.float32)\n    return out[0] if squeeze else out\n\n\ndef convert_action_10d_to_7d(action_10d: np.ndarray) -> np.ndarray:\n    \"\"\"Convert X-VLA 10D action to LIBERO 7D action.\n\n    Input: [pos(3), rot6d(6), gripper_sigmoid(1)]\n    Output: [pos(3), axis_angle(3), gripper_binary(1)]\n    \"\"\"\n    pos = action_10d[:3]\n    rot6d = action_10d[3:9]\n    gripper = action_10d[9:10]\n    axis_angle = rotate6d_to_axis_angle(rot6d)\n    gripper_binary = np.where(gripper > 0.5, 1.0, -1.0).astype(np.float32)\n    return np.concatenate([pos, axis_angle, gripper_binary]).astype(np.float32)\n\n\n# ---------------------------------------------------------------------------\n# Build batch for X-VLA\n# ---------------------------------------------------------------------------\n\ndef obs_to_xvla_inputs(obs, task_text, processor, device, dtype):\n    \"\"\"Convert LIBERO obs to X-VLA model inputs.\"\"\"\n    from PIL import Image as PILImage\n\n    # Image\n    raw_img = None\n    for key in (\"agentview_image\", \"image\"):\n        if key in obs.get(\"pixels\", {}):\n            raw_img = obs[\"pixels\"][key]\n            break\n    if raw_img is None:\n        raw_img = next(iter(obs[\"pixels\"].values()))\n    pil_img = PILImage.fromarray(raw_img)\n\n    # Use processor for image + text encoding\n    inputs = processor(images=[pil_img], language_instruction=task_text)\n\n    # State (proprio)\n    state = extract_state(obs)\n\n    # Move to device\n    result = {}\n    for k, v in inputs.items():\n        if isinstance(v, torch.Tensor):\n            result[k] = v.to(device=device, dtype=dtype) if v.is_floating_point() else v.to(device=device)\n        else:\n            result[k] = v\n\n    result[\"proprio\"] = torch.from_numpy(state).unsqueeze(0).to(device=device, dtype=dtype)\n    result[\"domain_id\"] = torch.zeros(1, dtype=torch.long, device=device)\n\n    return result\n\n\n# ---------------------------------------------------------------------------\n# L2-norm pruning monkey-patch\n# ---------------------------------------------------------------------------\n\ndef make_pruned_forward_vlm(k_ratio):\n    \"\"\"Return a patched forward_vlm that prunes vision tokens by L2 norm.\"\"\"\n\n    def pruned_forward_vlm(self, input_ids, pixel_values, image_mask):\n        batch_size, num_views = pixel_values.shape[:2]\n        flat_mask = image_mask.view(-1).to(dtype=torch.bool)\n        flat_images = pixel_values.flatten(0, 1)\n        num_valid = int(flat_mask.sum().item())\n        if num_valid == 0:\n            raise ValueError(\"At least one image view must be valid.\")\n\n        valid_images = flat_images[flat_mask]\n        valid_feats = self.vlm._encode_image(valid_images)\n        tokens_per_view, hidden_dim = valid_feats.shape[1:]\n\n        if k_ratio < 1.0:\n            k = max(1, int(tokens_per_view * k_ratio))\n            norms = valid_feats.norm(dim=-1)\n            _, topk_idx = norms.topk(k, dim=-1)\n            topk_idx = topk_idx.sort(dim=-1).values\n            valid_feats = torch.gather(\n                valid_feats, 1,\n                topk_idx.unsqueeze(-1).expand(-1, -1, hidden_dim)\n            )\n            tokens_per_view = k\n\n        image_features = valid_feats.new_zeros(\n            (batch_size * num_views, tokens_per_view, hidden_dim))\n        image_features[flat_mask] = valid_feats\n        image_features = image_features.view(\n            batch_size, num_views, tokens_per_view, hidden_dim)\n\n        inputs_embeds = self.vlm.get_input_embeddings()(input_ids)\n        merged_embeds, attention_mask = \\\n            self.vlm._merge_input_ids_with_image_features(\n                image_features[:, 0], inputs_embeds)\n\n        enc_out = self.vlm.language_model.model.encoder(\n            attention_mask=attention_mask,\n            inputs_embeds=merged_embeds,\n        )[0]\n\n        aux_visual_inputs = image_features[:, 1:].reshape(\n            batch_size, -1, hidden_dim)\n        return {\"vlm_features\": enc_out, \"aux_visual_inputs\": aux_visual_inputs}\n\n    return pruned_forward_vlm\n\n\n# ---------------------------------------------------------------------------\n# Wilson CI\n# ---------------------------------------------------------------------------\n\ndef wilson_ci(n_success, n_total, z=1.96):\n    if n_total == 0:\n        return 0.0, 0.0, 0.0\n    p = n_success / n_total\n    denom = 1 + z**2 / n_total\n    center = (p + z**2 / (2 * n_total)) / denom\n    margin = z * np.sqrt((p * (1 - p) + z**2 / (4 * n_total)) / n_total) / denom\n    return p, max(0, center - margin), min(1, center + margin)\n\n\n# ---------------------------------------------------------------------------\n# Main\n# ---------------------------------------------------------------------------\n\ndef main():\n    args = parse_args()\n    device = torch.device(f\"cuda:{args.gpu}\" if torch.cuda.is_available() else \"cpu\")\n\n    log.info(\"Loading X-VLA from %s\", args.pretrained_dir)\n    from transformers import AutoModel, AutoProcessor\n\n    model = AutoModel.from_pretrained(\n        args.pretrained_dir,\n        trust_remote_code=True,\n        torch_dtype=torch.float32,\n    )\n    model = model.to(device).eval()\n    model_dtype = next(model.parameters()).dtype\n\n    processor = AutoProcessor.from_pretrained(\n        args.pretrained_dir, trust_remote_code=True)\n\n    num_actions = model.num_actions\n    dim_action = model.action_space.dim_action\n    log.info(\"Model loaded: num_actions=%d, dim_action=%d, action_mode=%s\",\n             num_actions, dim_action, model.action_mode)\n\n    # Detect vision token count with dummy forward\n    with torch.no_grad():\n        dummy_img = torch.randn(1, 1, 3, 256, 256, device=device, dtype=model_dtype)\n        dummy_mask = torch.ones(1, 1, dtype=torch.bool, device=device)\n        dummy_ids = torch.zeros(1, 10, dtype=torch.long, device=device)\n        enc = model.forward_vlm(dummy_ids, dummy_img, dummy_mask)\n        n_vis_in_enc = enc[\"vlm_features\"].shape[1]\n        log.info(\"VLM encoder output: %d tokens (vision+text)\", n_vis_in_enc)\n        # Get raw vision token count\n        dummy_feats = model.vlm._encode_image(dummy_img[:, 0])\n        n_vis_tokens = dummy_feats.shape[1]\n        log.info(\"Vision tokens from _encode_image: %d\", n_vis_tokens)\n\n    # Apply L2-norm pruning\n    if args.k_ratio < 1.0:\n        k_actual = max(1, int(n_vis_tokens * args.k_ratio))\n        log.info(\"L2-norm pruning: k_ratio=%.2f → keeping %d/%d vision tokens\",\n                 args.k_ratio, k_actual, n_vis_tokens)\n        model.forward_vlm = types.MethodType(\n            make_pruned_forward_vlm(args.k_ratio), model)\n    else:\n        log.info(\"No pruning (baseline, k_ratio=1.0)\")\n\n    max_steps = args.max_steps or SUITE_MAX_STEPS.get(args.suite, 280)\n    if args.output:\n        output_path = Path(args.output)\n    else:\n        output_path = Path(f\"/root/autodl-tmp/importance_margin_vla_compress/results/\"\n                          f\"xvla_l2prune_{args.suite}_k{args.k_ratio:.2f}.json\")\n\n    log.info(\"Suite=%s, k=%.2f, max_steps=%d, eps=%d, horizon=%d, denoise_steps=%d\",\n             args.suite, args.k_ratio, max_steps, args.num_episodes,\n             args.action_horizon, args.num_denoising_steps)\n\n    # Load LIBERO\n    from libero.libero import benchmark\n    sys.path.insert(0, \"/root/autodl-tmp/lerobot/src\")\n    from lerobot.envs.libero import LiberoEnv\n\n    bench_dict = benchmark.get_benchmark_dict()\n    task_suite = bench_dict[args.suite]()\n    n_tasks = len(task_suite.tasks)\n    task_ids = list(range(n_tasks))\n    if args.task_ids:\n        task_ids = [int(x) for x in args.task_ids.split(\",\")]\n    log.info(\"Suite '%s': %d tasks, evaluating %s\", args.suite, n_tasks, task_ids)\n\n    all_task_results = {}\n    total_successes = 0\n    total_episodes = 0\n    eval_start = time_mod.time()\n\n    for task_id in task_ids:\n        task = task_suite.get_task(task_id)\n        task_desc = task.language\n        log.info(\"--- Task %d: %s ---\", task_id, task_desc)\n\n        env = LiberoEnv(\n            task_suite=task_suite,\n            task_id=task_id,\n            task_suite_name=args.suite,\n            camera_name=\"agentview_image\",\n            obs_type=\"pixels_agent_pos\",\n            observation_width=256,\n            observation_height=256,\n            init_states=True,\n            n_envs=args.num_episodes,\n            episode_index=0,\n            control_mode=\"relative\",\n        )\n\n        task_successes = []\n        task_lengths = []\n\n        for ep in range(args.num_episodes):\n            obs, info = env.reset(seed=args.seed + task_id * 1000 + ep)\n            action_chunk = None\n            action_idx = 0\n            success = False\n\n            for step in range(max_steps):\n                if action_chunk is None or action_idx >= args.action_horizon:\n                    inputs = obs_to_xvla_inputs(\n                        obs, task_desc, processor, device, model_dtype)\n\n                    with torch.no_grad():\n                        raw_actions = model.generate_actions(\n                            **inputs, steps=args.num_denoising_steps)\n                    # raw_actions: [1, num_actions, dim_action] with sigmoid gripper\n                    raw_chunk = raw_actions[0].cpu().numpy()  # [30, 10]\n\n                    # Convert 10D -> 7D for each action\n                    action_chunk = np.array([\n                        convert_action_10d_to_7d(raw_chunk[i])\n                        for i in range(raw_chunk.shape[0])\n                    ])\n                    action_idx = 0\n\n                action = action_chunk[action_idx].copy()\n                action = np.clip(action, -1.0, 1.0).astype(np.float32)\n                action_idx += 1\n\n                obs, reward, terminated, truncated, info = env.step(action)\n\n                if info.get(\"is_success\", False):\n                    success = True\n                    break\n                if terminated or truncated:\n                    break\n\n            ep_steps = step + 1\n            task_successes.append(success)\n            task_lengths.append(ep_steps)\n            log.info(\"  Ep %d/%d | %s | steps=%d\",\n                     ep + 1, args.num_episodes,\n                     \"SUCCESS\" if success else \"FAIL\", ep_steps)\n\n        env.close()\n\n        n_succ = sum(task_successes)\n        sr = n_succ / args.num_episodes if args.num_episodes > 0 else 0.0\n        all_task_results[task_id] = {\n            \"task_id\": task_id,\n            \"task_description\": task_desc,\n            \"success_count\": n_succ,\n            \"total_episodes\": args.num_episodes,\n            \"success_rate\": round(sr, 4),\n            \"mean_steps\": round(float(np.mean(task_lengths)), 1),\n        }\n        total_successes += n_succ\n        total_episodes += args.num_episodes\n        log.info(\"  Task %d SR: %d/%d (%.1f%%)\",\n                 task_id, n_succ, args.num_episodes, sr * 100)\n\n    elapsed = time_mod.time() - eval_start\n    overall_sr = total_successes / total_episodes if total_episodes > 0 else 0.0\n    _, ci_lo, ci_hi = wilson_ci(total_successes, total_episodes)\n\n    log.info(\"=\" * 60)\n    log.info(\"X-VLA | SUITE: %s | k_ratio: %.2f | L2-norm pruning\",\n             args.suite, args.k_ratio)\n    log.info(\"Overall SR: %d/%d (%.1f%%)\",\n             total_successes, total_episodes, overall_sr * 100)\n    log.info(\"95%% Wilson CI: [%.1f%%, %.1f%%]\", ci_lo * 100, ci_hi * 100)\n    for tid, tr in sorted(all_task_results.items()):\n        log.info(\"  Task %d: %.0f%% (%d/%d) -- %s\",\n                 tid, tr[\"success_rate\"] * 100, tr[\"success_count\"],\n                 tr[\"total_episodes\"], tr[\"task_description\"])\n    log.info(\"Elapsed: %.1f min\", elapsed / 60)\n    log.info(\"=\" * 60)\n\n    summary = {\n        \"model\": \"xvla\",\n        \"pretrained_dir\": args.pretrained_dir,\n        \"mode\": \"l2_norm_prune\",\n        \"suite\": args.suite,\n        \"k_ratio\": args.k_ratio,\n        \"n_vision_tokens\": n_vis_tokens,\n        \"k_tokens_kept\": max(1, int(n_vis_tokens * args.k_ratio)) if args.k_ratio < 1.0 else n_vis_tokens,\n        \"total_episodes\": total_episodes,\n        \"total_successes\": total_successes,\n        \"overall_success_rate\": round(overall_sr, 4),\n        \"wilson_ci_95\": [round(ci_lo, 4), round(ci_hi, 4)],\n        \"num_episodes_per_task\": args.num_episodes,\n        \"max_steps\": max_steps,\n        \"action_horizon\": args.action_horizon,\n        \"num_denoising_steps\": args.num_denoising_steps,\n        \"seed\": args.seed,\n        \"elapsed_seconds\": round(elapsed, 1),\n        \"per_task\": all_task_results,\n    }\n    output_path.parent.mkdir(parents=True, exist_ok=True)\n    with open(output_path, \"w\") as f:\n        json.dump(summary, f, indent=2)\n    log.info(\"Results saved to %s\", output_path)\n\n    return summary\n\n\nif __name__ == \"__main__\":\n    main()\n"},"caller":{"type":"direct"}}],"stop_reason":null,"stop_sequence":null,"stop_details":null,"usage":{"input_tokens":1,"cache_creation_input_tokens":333,"cache_read_input_tokens":130505,"cache_creation":{"ephemeral_5m_input_tokens":0,"ephemeral_1h_input_tokens":333},"output_tokens":1,"service_tier":"standard","inference_geo":"not_available"},"diagnostics":null,"context_management":null},"parent_tool_use_id":null,"session_id":"c40ae7ef-a084-4ae1-a944-62300c4448d8","uuid":"c2d795b8-145b-4fd8-9299-237e0b2b2370"}
