 $(date)\"\n    echo \"\"\ndone\n\necho \"===== All sweeps complete =====\"\n\n# Collect results summary\npython3 -c \"\nimport json, glob\nresults = {}\nfor f in sorted(glob.glob('eval_results/xvla_prune_k*_${SUITE}.json')):\n    with open(f) as fh:\n        d = json.load(fh)\n    k = d['keep_ratio']\n    results[k] = {\n        'sr': d['overall_success_rate'],\n        'ci': d['wilson_ci_95'],\n        'tokens_kept': d['n_vision_tokens_kept'],\n        'tokens_total': d['n_vision_tokens_original'],\n    }\n\nprint('\\n===== X-VLA Pruning Results Summary =====')\nprint(f'{'k':>6} {'SR%':>8} {'95% CI':>16} {'Tokens':>12}')\nprint('-' * 46)\nfor k in sorted(results.keys(), reverse=True):\n    r = results[k]\n    print(f'{k:>6.2f} {r[\\\"sr\\\"]*100:>7.1f}% [{r[\\\"ci\\\"][0]*100:.1f}%, {r[\\\"ci\\\"][1]*100:.1f}%] {r[\\\"tokens_kept\\\"]:>4}/{r[\\\"tokens_total\\\"]:>4}')\n\"\n","structuredPatch":[{"oldStart":5,"oldLines":7,"newStart":5,"newLines":7,"lines":[" set -e"," "," export MUJOCO_GL=egl","-export CUDA_VISIBLE_DEVICES=0","+export CUDA_VISIBLE_DEVICES=1"," export TRANSFORMERS_OFFLINE=1"," export HF_HUB_OFFLINE=1"," export HF_HOME=/root/autodl-tmp/.hf_cache"]}],"userModified":false,"replaceAll":false}}
